document.addEventListener('DOMContentLoaded', function () {
  'use strict';

  // ==========================================
  // 1. 流星尾迹鼠标效果
  // ==========================================
  const trailCanvas = document.getElementById('trailCanvas');
  const trailCtx = trailCanvas.getContext('2d');
  let trailParticles = [];
  let mouseX = 0, mouseY = 0;
  let lastMouseX = 0, lastMouseY = 0;
  let mouseSpeed = 0;

  function resizeTrailCanvas() {
    trailCanvas.width = window.innerWidth;
    trailCanvas.height = window.innerHeight;
  }
  resizeTrailCanvas();
  window.addEventListener('resize', resizeTrailCanvas);

  document.addEventListener('mousemove', (e) => {
    lastMouseX = mouseX;
    lastMouseY = mouseY;
    mouseX = e.clientX;
    mouseY = e.clientY;

    // 计算鼠标速度
    const dx = mouseX - lastMouseX;
    const dy = mouseY - lastMouseY;
    mouseSpeed = Math.min(Math.sqrt(dx * dx + dy * dy), 30);

    // 根据速度生成粒子
    if (mouseSpeed > 2) {
      const count = Math.floor(mouseSpeed / 4) + 1;
      for (let i = 0; i < count; i++) {
        createTrailParticle(
          mouseX + (Math.random() - 0.5) * 10,
          mouseY + (Math.random() - 0.5) * 10
        );
      }
    }
  });

  function createTrailParticle(x, y) {
    const colors = [
      'rgba(139, 92, 246, ',
      'rgba(167, 139, 250, ',
      'rgba(6, 182, 212, ',
      'rgba(244, 114, 182, '
    ];
    trailParticles.push({
      x: x,
      y: y,
      vx: (Math.random() - 0.5) * 1.5,
      vy: (Math.random() - 0.5) * 1.5 - 0.5,
      radius: Math.random() * 3 + 1.5,
      life: 1,
      decay: Math.random() * 0.02 + 0.012,
      color: colors[Math.floor(Math.random() * colors.length)]
    });

    if (trailParticles.length > 200) {
      trailParticles.shift();
    }
  }

  function animateTrail() {
    trailCtx.clearRect(0, 0, trailCanvas.width, trailCanvas.height);

    // 绘制尾迹连线
    if (trailParticles.length > 1) {
      trailCtx.beginPath();
      trailCtx.moveTo(trailParticles[0].x, trailParticles[0].y);
      for (let i = 1; i < trailParticles.length; i++) {
        const p = trailParticles[i];
        if (p.life > 0.3) {
          trailCtx.lineTo(p.x, p.y);
        }
      }
      trailCtx.strokeStyle = 'rgba(139, 92, 246, 0.15)';
      trailCtx.lineWidth = 2;
      trailCtx.lineCap = 'round';
      trailCtx.lineJoin = 'round';
      trailCtx.stroke();
    }

    // 绘制粒子
    for (let i = trailParticles.length - 1; i >= 0; i--) {
      const p = trailParticles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.vy += 0.02; // 轻微重力
      p.life -= p.decay;
      p.radius *= 0.98;

      if (p.life <= 0 || p.radius < 0.2) {
        trailParticles.splice(i, 1);
        continue;
      }

      // 发光粒子
      const gradient = trailCtx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.radius * 3);
      gradient.addColorStop(0, p.color + (p.life * 0.9) + ')');
      gradient.addColorStop(0.4, p.color + (p.life * 0.4) + ')');
      gradient.addColorStop(1, p.color + '0)');

      trailCtx.beginPath();
      trailCtx.arc(p.x, p.y, p.radius * 3, 0, Math.PI * 2);
      trailCtx.fillStyle = gradient;
      trailCtx.fill();

      // 核心亮点
      trailCtx.beginPath();
      trailCtx.arc(p.x, p.y, p.radius * 0.5, 0, Math.PI * 2);
      trailCtx.fillStyle = 'rgba(255, 255, 255, ' + (p.life * 0.8) + ')';
      trailCtx.fill();
    }

    requestAnimationFrame(animateTrail);
  }
  animateTrail();

  // ==========================================
  // 2. 网格翻砖滚动过渡（canvas）
  // ==========================================
  const gridCanvas = document.getElementById('gridCanvas');
  const gridCtx = gridCanvas.getContext('2d');
  const sectionList = document.querySelectorAll('.section');

  // 浅色主题各 section 的颜色
  const themeColors = [
    { bg: '#f8f9fc', grid: 'rgba(109, 40, 217, 0.07)', accent: '#8b5cf6' },   // Hero - 紫
    { bg: '#f5f9fb', grid: 'rgba(8, 145, 178, 0.07)', accent: '#06b6d4' },   // About - 青
    { bg: '#faf6fc', grid: 'rgba(219, 39, 119, 0.06)', accent: '#ec4899' },  // Skills - 粉
    { bg: '#f6f8fc', grid: 'rgba(37, 99, 235, 0.07)', accent: '#3b82f6' },  // Projects - 蓝
    { bg: '#fcf9f5', grid: 'rgba(217, 119, 6, 0.06)', accent: '#f59e0b' },  // Ideas - 橙
    { bg: '#f5faf7', grid: 'rgba(5, 150, 105, 0.06)', accent: '#10b981' },  // Notes - 绿
    { bg: '#f8f9fc', grid: 'rgba(109, 40, 217, 0.07)', accent: '#8b5cf6' }  // Contact - 紫
  ];

  const TILE_SIZE = 36; // 网格块大小
  let gridCols = 0, gridRows = 0;
  let tiles = []; // 每个方块的状态
  let currentThemeIdx = 0;
  let nextThemeIdx = 0;

  // 给每个 section 注入光晕元素
  sectionList.forEach((section) => {
    const glow1 = document.createElement('div');
    glow1.className = 'section-glow glow-1';
    const glow2 = document.createElement('div');
    glow2.className = 'section-glow glow-2';
    section.insertBefore(glow1, section.firstChild);
    section.insertBefore(glow2, section.firstChild);
  });

  function resizeGridCanvas() {
    const dpr = window.devicePixelRatio || 1;
    gridCanvas.width = window.innerWidth * dpr;
    gridCanvas.height = window.innerHeight * dpr;
    gridCanvas.style.width = window.innerWidth + 'px';
    gridCanvas.style.height = window.innerHeight + 'px';
    gridCtx.scale(dpr, dpr);

    gridCols = Math.ceil(window.innerWidth / TILE_SIZE) + 2;
    gridRows = Math.ceil(window.innerHeight / TILE_SIZE) + 2;

    // 初始化所有方块
    tiles = [];
    for (let r = 0; r < gridRows; r++) {
      tiles[r] = [];
      for (let c = 0; c < gridCols; c++) {
        tiles[r][c] = {
          flipProgress: 0,  // 0 = 当前色, 1 = 新色
          flipping: false,
          delay: 0
        };
      }
    }
  }
  resizeGridCanvas();
  window.addEventListener('resize', resizeGridCanvas);

  // hex 转 rgba
  function hexToRgba(hex, alpha) {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
  }

  // 颜色插值
  function lerpColor(color1, color2, t) {
    // 解析 rgba
    const parse = (c) => {
      const m = c.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\)/);
      if (m) {
        return [parseInt(m[1]), parseInt(m[2]), parseInt(m[3]), parseFloat(m[4] || 1)];
      }
      return [0, 0, 0, 1];
    };
    const [r1, g1, b1, a1] = parse(color1);
    const [r2, g2, b2, a2] = parse(color2);
    const r = Math.round(r1 + (r2 - r1) * t);
    const g = Math.round(g1 + (g2 - g1) * t);
    const b = Math.round(b1 + (b2 - b1) * t);
    const a = (a1 + (a2 - a1) * t).toFixed(3);
    return `rgba(${r}, ${g}, ${b}, ${a})`;
  }

  // 计算两个 section 之间的滚动进度 (0-1)
  function getScrollProgress() {
    const scrollY = window.scrollY;
    const viewportH = window.innerHeight;

    // 找到当前跨越的边界
    for (let i = 0; i < sectionList.length - 1; i++) {
      const sectionBottom = sectionList[i].offsetTop + sectionList[i].offsetHeight;
      const nextSectionBottom = sectionList[i + 1].offsetTop + sectionList[i + 1].offsetHeight;

      // 当视窗中间在两个 section 之间时
      const midPoint = scrollY + viewportH * 0.5;
      const boundary = sectionList[i + 1].offsetTop;

      // 以边界为中心，前后各半屏作为过渡区域
      const transitionZone = viewportH * 0.8;
      const start = boundary - transitionZone * 0.5;
      const end = boundary + transitionZone * 0.5;

      if (midPoint >= start && midPoint <= end) {
        const progress = (midPoint - start) / (end - start);
        return {
          fromIdx: i,
          toIdx: i + 1,
          progress: Math.max(0, Math.min(1, progress))
        };
      }
    }

    // 不在过渡区域，返回当前所在 section
    let currentIdx = 0;
    const midPoint = scrollY + viewportH * 0.5;
    for (let i = 0; i < sectionList.length; i++) {
      const top = sectionList[i].offsetTop;
      const bottom = top + sectionList[i].offsetHeight;
      if (midPoint >= top && midPoint < bottom) {
        currentIdx = i;
        break;
      }
    }
    return { fromIdx: currentIdx, toIdx: currentIdx, progress: 0 };
  }

  // 触发翻砖动画
  let lastFromIdx = 0;
  let lastToIdx = 0;
  let lastProgress = 0;

  function updateGridFlip() {
    const { fromIdx, toIdx, progress } = getScrollProgress();

    // 如果跨越了新的边界，重置所有方块
    if (fromIdx !== lastFromIdx || toIdx !== lastToIdx) {
      lastFromIdx = fromIdx;
      lastToIdx = toIdx;

      // 如果是同一个 section，全部重置为 0
      if (fromIdx === toIdx) {
        for (let r = 0; r < gridRows; r++) {
          for (let c = 0; c < gridCols; c++) {
            tiles[r][c].flipProgress = 0;
            tiles[r][c].flipping = false;
          }
        }
        currentThemeIdx = fromIdx;
        nextThemeIdx = fromIdx;
        document.body.style.backgroundColor = themeColors[fromIdx].bg;
      } else {
         // 新的过渡开始，计算每块的延迟（从上到下波浪式）
         const dir = toIdx > fromIdx ? 1 : -1;
         for (let r = 0; r < gridRows; r++) {
           for (let c = 0; c < gridCols; c++) {
             // 从上往下按行分布延迟，每列加一点随机偏移
             const normalizedRow = dir > 0 ? r / gridRows : (gridRows - r) / gridRows;
             tiles[r][c].delay = normalizedRow * 0.5 + Math.random() * 0.12;
             tiles[r][c].flipping = false;
             // 如果往回滚，重置进度
             if (dir < 0 && tiles[r][c].flipProgress > 0.5) {
               tiles[r][c].flipProgress = 1 - tiles[r][c].flipProgress;
             }
           }
         }
         currentThemeIdx = fromIdx;
         nextThemeIdx = toIdx;
       }
    }

    lastProgress = progress;

    // 更新每块的翻转进度
    if (fromIdx !== toIdx) {
      for (let r = 0; r < gridRows; r++) {
        for (let c = 0; c < gridCols; c++) {
          const tile = tiles[r][c];
          const effectiveProgress = Math.max(0, Math.min(1, (progress - tile.delay) / 0.4));
          tile.flipProgress = effectiveProgress;
        }
      }

      // body 背景色在进度 50% 左右切换
      if (progress > 0.5) {
        document.body.style.backgroundColor = themeColors[toIdx].bg;
      } else {
        document.body.style.backgroundColor = themeColors[fromIdx].bg;
      }
    }
  }

  // 绘制网格
  function drawGrid() {
    const W = window.innerWidth;
    const H = window.innerHeight;
    gridCtx.clearRect(0, 0, W, H);

    const fromColor = themeColors[currentThemeIdx]?.grid || 'rgba(109, 40, 217, 0.07)';
    const toColor = themeColors[nextThemeIdx]?.grid || 'rgba(109, 40, 217, 0.07)';
    const fromAccent = themeColors[currentThemeIdx]?.accent || '#8b5cf6';
    const toAccent = themeColors[nextThemeIdx]?.accent || '#8b5cf6';

    for (let r = 0; r < gridRows; r++) {
      for (let c = 0; c < gridCols; c++) {
        const x = c * TILE_SIZE;
        const y = r * TILE_SIZE;
        const tile = tiles[r][c];
        const p = tile.flipProgress;

        // 方块的翻转效果：用缩放模拟垂直翻转（上下翻）
        // 进度 0-0.5: 正面缩窄，0.5-1: 背面展开
        let scaleY = 1;
        let color;

        if (p < 0.5) {
          // 前半段：从当前色翻到边缘
          scaleY = 1 - p * 1.6;
          color = fromColor;
        } else {
          // 后半段：从边缘展开到新色
          scaleY = (p - 0.5) * 1.6 + 0.2;
          color = toColor;
        }

        scaleY = Math.max(0.05, Math.min(1, scaleY));

        const drawH = TILE_SIZE * scaleY;
        const drawY = y + (TILE_SIZE - drawH) / 2;

        // 翻转中的方块，填充一点颜色增加立体感
        if (p > 0 && p < 1) {
          gridCtx.fillStyle = color.replace(/[\d.]+\)$/, (parseFloat(color.match(/[\d.]+\)$/)?.[0] || 0.07) * 1.5).toFixed(3) + ')');
          gridCtx.fillRect(x + 1, drawY + 1, TILE_SIZE - 2, drawH - 2);
        }

        // 网格线（四边）
        gridCtx.strokeStyle = color;
        gridCtx.lineWidth = 1;
        gridCtx.strokeRect(x + 0.5, drawY + 0.5, TILE_SIZE - 1, drawH - 1);
      }
    }

    // 中心径向渐变遮罩（边缘淡出）
    const gradient = gridCtx.createRadialGradient(
      W / 2, H / 2, Math.min(W, H) * 0.25,
      W / 2, H / 2, Math.max(W, H) * 0.65
    );
    gradient.addColorStop(0, 'rgba(0,0,0,0)');
    gradient.addColorStop(1, themeColors[currentThemeIdx]?.bg || '#f8f9fc');

    requestAnimationFrame(drawGrid);
  }
  drawGrid();

  // 滚动监听
  let scrollThrottle = false;
  window.addEventListener('scroll', () => {
    if (!scrollThrottle) {
      scrollThrottle = true;
      requestAnimationFrame(() => {
        updateGridFlip();
        scrollThrottle = false;
      });
    }
  }, { passive: true });

  // 初始化 body 背景
  document.body.style.backgroundColor = themeColors[0].bg;

  // ==========================================
  // 3. 粒子背景
  // ==========================================
  const canvas = document.getElementById('particleCanvas');
  const ctx = canvas.getContext('2d');
  let particles = [];
  let W = 0, H = 0;

  function resizeCanvas() {
    W = canvas.width = window.innerWidth;
    H = canvas.height = window.innerHeight;
    createParticles();
  }

  function createParticles() {
    particles = [];
    const count = Math.floor((W * H) / 18000);
    for (let i = 0; i < count; i++) {
      particles.push({
        x: Math.random() * W,
        y: Math.random() * H,
        vx: (Math.random() - 0.5) * 0.25,
        vy: (Math.random() - 0.5) * 0.25,
        radius: Math.random() * 1.2 + 0.4,
        opacity: Math.random() * 0.4 + 0.15
      });
    }
  }

  function drawParticles() {
    ctx.clearRect(0, 0, W, H);

    // 粒子
    for (let i = 0; i < particles.length; i++) {
      const p = particles[i];
      p.x += p.vx;
      p.y += p.vy;

      if (p.x < 0) p.x = W;
      if (p.x > W) p.x = 0;
      if (p.y < 0) p.y = H;
      if (p.y > H) p.y = 0;

      // 鼠标引力
      const dx = mouseX - p.x;
      const dy = mouseY - p.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < 120) {
        const force = (120 - dist) / 120 * 0.015;
        p.vx += (dx / dist) * force;
        p.vy += (dy / dist) * force;
      }

      // 速度衰减
      p.vx *= 0.99;
      p.vy *= 0.99;

      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(109, 40, 217, ${p.opacity * 0.5})`;
      ctx.fill();
    }

    // 连线
    for (let i = 0; i < particles.length; i++) {
      for (let j = i + 1; j < particles.length; j++) {
        const dx = particles[i].x - particles[j].x;
        const dy = particles[i].y - particles[j].y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < 100) {
          const opacity = (1 - dist / 100) * 0.15;
          ctx.beginPath();
          ctx.moveTo(particles[i].x, particles[i].y);
          ctx.lineTo(particles[j].x, particles[j].y);
          ctx.strokeStyle = `rgba(109, 40, 217, ${opacity * 0.4})`;
          ctx.lineWidth = 0.5;
          ctx.stroke();
        }
      }
    }

    requestAnimationFrame(drawParticles);
  }

  resizeCanvas();
  drawParticles();
  window.addEventListener('resize', resizeCanvas);

  // ==========================================
  // 4. 滚动进度条
  // ==========================================
  const progressBar = document.createElement('div');
  progressBar.className = 'scroll-progress';
  document.body.appendChild(progressBar);

  window.addEventListener('scroll', () => {
    const scrollTop = window.scrollY;
    const docHeight = document.documentElement.scrollHeight - window.innerHeight;
    const progress = (scrollTop / docHeight) * 100;
    progressBar.style.width = progress + '%';
  }, { passive: true });

  // ==========================================
  // 5. 导航栏滚动效果
  // ==========================================
  const navbar = document.querySelector('.navbar');
  const navLinks = document.querySelectorAll('.nav-link');
  const navToggle = document.querySelector('.nav-toggle');
  const navMenu = document.querySelector('.nav-menu');

  window.addEventListener('scroll', () => {
    if (window.scrollY > 50) {
      navbar.classList.add('scrolled');
    } else {
      navbar.classList.remove('scrolled');
    }

    // 导航高亮
    const scrollPos = window.scrollY + 120;
    let currentSection = '';

    sectionList.forEach(section => {
      const top = section.offsetTop;
      const height = section.offsetHeight;
      if (scrollPos >= top && scrollPos < top + height) {
        currentSection = section.getAttribute('id');
      }
    });

    navLinks.forEach(link => {
      link.classList.remove('active');
      if (link.getAttribute('href') === '#' + currentSection) {
        link.classList.add('active');
      }
    });
  }, { passive: true });

  // 移动端菜单
  if (navToggle) {
    navToggle.addEventListener('click', () => {
      navToggle.classList.toggle('active');
      navMenu.classList.toggle('open');
    });

    navLinks.forEach(link => {
      link.addEventListener('click', () => {
        navToggle.classList.remove('active');
        navMenu.classList.remove('open');
      });
    });
  }

  // ==========================================
  // 6. 滚动显示动画 (IntersectionObserver)
  // ==========================================
  const revealElements = document.querySelectorAll('.reveal');
  const levelBars = document.querySelectorAll('.level-bar');

  const revealObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');

        // 技能条动画
        if (entry.target.classList.contains('bento-large')) {
          const bar = entry.target.querySelector('.level-bar');
          if (bar) {
            const targetWidth = bar.style.width;
            bar.style.width = '0';
            setTimeout(() => {
              bar.style.width = targetWidth;
            }, 200);
          }
        }
      }
    });
  }, {
    threshold: 0.1,
    rootMargin: '0px 0px -60px 0px'
  });

  revealElements.forEach(el => revealObserver.observe(el));

  // ==========================================
  // 7. 3D 卡片倾斜效果
  // ==========================================
  const tiltCards = document.querySelectorAll('.tilt-card, .project-card, .idea-card, .note-card, .contact-item');

  tiltCards.forEach(card => {
    card.addEventListener('mousemove', (e) => {
      const rect = card.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      const centerX = rect.width / 2;
      const centerY = rect.height / 2;
      const rotateX = (y - centerY) / 25;
      const rotateY = (centerX - x) / 25;

      card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) translateY(-6px) scale(1.015)`;
    });

    card.addEventListener('mouseleave', () => {
      card.style.transform = '';
    });
  });

  // ==========================================
  // 8. 项目筛选
  // ==========================================
  const filterBtns = document.querySelectorAll('.filter-btn');
  const projectCards = document.querySelectorAll('.project-card');

  filterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      filterBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      const filter = btn.getAttribute('data-filter');

      projectCards.forEach(card => {
        const type = card.getAttribute('data-type');
        if (filter === 'all' || filter === type) {
          card.classList.remove('hidden');
          card.style.animation = 'fadeInUp 0.5s ease both';
        } else {
          card.classList.add('hidden');
        }
      });
    });
  });

  // ==========================================
  // 9. 数字计数动画
  // ==========================================
  const counters = document.querySelectorAll('.mini-num');

  function animateCounter(el) {
    const target = parseInt(el.getAttribute('data-target') || el.textContent);
    const duration = 1800;
    const start = performance.now();

    function step(now) {
      const progress = Math.min((now - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      const current = Math.floor(eased * target);
      el.textContent = current + (el.getAttribute('data-suffix') || '');
      if (progress < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  const counterObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const stats = entry.target.querySelectorAll('.mini-num');
        stats.forEach(s => animateCounter(s));
        counterObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.5 });

  const statsRow = document.querySelector('.hero-stats-row');
  if (statsRow) counterObserver.observe(statsRow);

  // ==========================================
  // 10. Hero 视差效果
  // ==========================================
  const heroOrb = document.querySelector('.hero-orb');
  const floatTags = document.querySelectorAll('.float-tag');
  const heroGlows = document.querySelectorAll('.hero-glow');

  document.addEventListener('mousemove', (e) => {
    const x = (e.clientX / window.innerWidth - 0.5) * 2;
    const y = (e.clientY / window.innerHeight - 0.5) * 2;

    if (heroOrb) {
      heroOrb.style.transform = `translate(${x * 20}px, ${y * 20}px)`;
    }

    floatTags.forEach((tag, i) => {
      const factor = (i + 1) * 6;
      tag.style.transform = `translate(${x * factor}px, ${y * factor}px)`;
    });

    heroGlows.forEach((glow, i) => {
      const factor = (i + 1) * 15;
      glow.style.transform = `translate(${x * factor}px, ${y * factor}px)`;
    });
  });

  // ==========================================
  // 11. 回到顶部
  // ==========================================
  const backToTop = document.querySelector('.back-to-top');

  window.addEventListener('scroll', () => {
    if (window.scrollY > 500) {
      backToTop.classList.add('visible');
    } else {
      backToTop.classList.remove('visible');
    }
  }, { passive: true });

  if (backToTop) {
    backToTop.addEventListener('click', () => {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }

  // ==========================================
  // 12. 表单提交
  // ==========================================
  const contactForm = document.querySelector('.contact-form form');
  if (contactForm) {
    contactForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const btn = contactForm.querySelector('button[type="submit"]');
      const originalText = btn.innerHTML;
      btn.innerHTML = '<span class="btn-text-deco">[</span>发送中...<span class="btn-text-deco">]</span>';
      btn.disabled = true;

      setTimeout(() => {
        btn.innerHTML = '<span class="btn-text-deco">[</span>已收到！<span class="btn-arrow">✓</span><span class="btn-text-deco">]</span>';
        btn.style.background = 'var(--gradient-3)';

        setTimeout(() => {
          btn.innerHTML = originalText;
          btn.disabled = false;
          btn.style.background = '';
          contactForm.reset();
        }, 2500);
      }, 1200);
    });
  }

  // ==========================================
  // 13. 平滑滚动
  // ==========================================
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
      e.preventDefault();
      const target = document.querySelector(this.getAttribute('href'));
      if (target) {
        target.scrollIntoView({
          behavior: 'smooth',
          block: 'start'
        });
      }
    });
  });

});
